from unittest import mock

class FakeConnection(object):
    def __init__(self):
        self._conn_closed = False
        self.connected = True

    def get_option(self, name):
        return {
            'persistent_log_messages': False,
            'persistent_connect_timeout': 9,
            'persistent_command_timeout': 11,
        }[name]

class FakeClientSocket(object):
    def __init__(self):
        self.closed = False

    def close(self):
        self.closed = True

class FakeListeningSocket(object):
    def __init__(self, connection, client):
        self.connection = connection
        self.client = client
        self.accept_calls = 0

    def accept(self):
        self.accept_calls += 1
        self.connection._conn_closed = True
        return self.client, None

class FakeServer(object):
    def __init__(self):
        self.requests = []

    def handle_request(self, data):
        self.requests.append(data)
        return '{"result":"ok"}'

class FakeSignal(object):
    SIGALRM = 14
    SIGTERM = 15

    def __init__(self):
        self.alarms = []

    def signal(self, signum, handler):
        return None

    def alarm(self, seconds):
        self.alarms.append(seconds)

connection = FakeConnection()
client = FakeClientSocket()
listener = FakeListeningSocket(connection, client)
server = FakeServer()
fake_signal = FakeSignal()
received = [b'{"method":"ping"}', b'']
sent = []
shutdown_calls = []

def fake_recv_data(sock):
    assert sock is client
    return received.pop(0)

def fake_send_data(sock, data):
    sent.append((sock, data))

process = ConnectionProcess(
    fd=None,
    play_context=None,
    socket_path='/tmp/test-connection.sock',
    original_path='/tmp',
)
process.connection = connection
process.sock = listener
process.srv = server
process.shutdown = lambda: shutdown_calls.append(True)

with mock.patch.dict(
    ConnectionProcess.run.__globals__,
    {
        'recv_data': fake_recv_data,
        'send_data': fake_send_data,
        'signal': fake_signal,
    },
), mock.patch.object(time, 'sleep', return_value=None):
    result = process.run()

assert result is None
assert listener.accept_calls == 1
assert server.requests == [b'{"method":"ping"}']
assert sent == [(client, b'{"result":"ok"}')]
assert client.closed is True
assert fake_signal.alarms == [9, 0, 11, 0]
assert shutdown_calls == [True]
